    ('83fda84a-8179-576f-8c5d-7c33adfc4781'::uuid, '5c9dc93a-cb56-555e-b539-7332c0d79a1e'::uuid, 'Quels ports s’enrichissent avec le grand commerce au XVIIIe siècle ?', 'mcq', '["Bordeaux, Nantes, Liverpool, Bristol","Paris, Lyon, Milan","Moscou, Varsovie","Vienne, Prague"]'::jsonb, 0, 'Ce sont des ports de l’Atlantique.', 1),
    ('94b00d11-b71a-596d-a0b0-dbd31fdd1361'::uuid, '5c9dc93a-cb56-555e-b539-7332c0d79a1e'::uuid, 'Quelles sont les trois étapes du commerce triangulaire ?', 'mcq', '["Europe → Afrique → Amérique → Europe","Europe → Asie → Afrique","Amérique → Europe → Asie","Afrique → Europe → Asie"]'::jsonb, 0, 'Chaque étape rapporte.', 2),
    ('8535f62c-0ab4-579c-9db5-02e0cc517d1f'::uuid, '5c9dc93a-cb56-555e-b539-7332c0d79a1e'::uuid, 'Combien d’Africains ont été déportés par la traite atlantique ?', 'mcq', '["Environ 12 millions","Environ 1 million","Environ 100 000","Environ 50 millions"]'::jsonb, 0, 'Entre le XVIe et le XIXe siècle.', 3),
    ('594de838-ca19-55b8-8ed3-aef9cf8f799c'::uuid, '5c9dc93a-cb56-555e-b539-7332c0d79a1e'::uuid, 'Que définit le Code Noir de 1685 ?', 'mcq', '["Le statut de l’esclave comme bien meuble","Les droits des marins","Les tarifs douaniers","Le droit de vote"]'::jsonb, 0, 'Une chose que l’on possède et transmet.', 4),
