    ('6e49dd1e-ebbf-5f64-88ef-ca9cdb27aff3'::uuid, '5c9dc93a-cb56-555e-b539-7332c0d79a1e'::uuid, 'Que produisent les plantations coloniales ?', 'mcq', '["Sucre, café, cacao, coton, tabac","Blé et seigle","Fer et charbon","Laine et lin"]'::jsonb, 0, 'Elles sont tournées vers l’exportation.', 6),
    ('b09a73b7-239c-5450-8310-15b1c02430d7'::uuid, '5c9dc93a-cb56-555e-b539-7332c0d79a1e'::uuid, 'En quelle année l’esclavage est-il définitivement aboli en France ?', 'mcq', '["1848","1794","1802","1789"]'::jsonb, 0, 'L’abolition de 1794 avait été annulée en 1802.', 7),
    ('72284631-e8b8-53b7-8a8b-561848a63b20'::uuid, '5c9dc93a-cb56-555e-b539-7332c0d79a1e'::uuid, 'La bourgeoisie négociante du XVIIIe siècle appartenait à la noblesse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle s’enrichit sans être noble — d’où sa frustration politique.', 8),
    ('3677291e-b1f0-53c9-b9ba-caf31c73e07a'::uuid, '9a4c26dd-f83e-5a15-a234-7f3deaa4e246'::uuid, 'Quel principe est au cœur des Lumières ?', 'mcq', '["La raison doit éclairer le monde","La tradition doit être respectée","L’autorité religieuse prime","La force fait le droit"]'::jsonb, 0, 'Contre la tradition et l’autorité.', 1),
    ('67e7d3da-8356-50a6-8fb3-7a255034a59e'::uuid, '9a4c26dd-f83e-5a15-a234-7f3deaa4e246'::uuid, 'Qui a théorisé la séparation des pouvoirs ?', 'mcq', '["Montesquieu","Voltaire","Rousseau","Diderot"]'::jsonb, 0, 'Dans De l’esprit des lois, en 1748.', 2),
    ('16cbe1ad-dd56-52a4-b3ea-7bfca67a3f0f'::uuid, '9a4c26dd-f83e-5a15-a234-7f3deaa4e246'::uuid, 'Quelle œuvre Diderot et d’Alembert dirigent-ils ?', 'mcq', '["L’Encyclopédie","Le Contrat social","Candide","De l’esprit des lois"]'::jsonb, 0, '28 volumes, de 1751 à 1772.', 3),
    ('00c2b6c7-0fed-538b-8bf7-dedaf97d6f8d'::uuid, '9a4c26dd-f83e-5a15-a234-7f3deaa4e246'::uuid, 'Quelle idée Rousseau défend-il dans Du contrat social ?', 'mcq', '["La souveraineté du peuple","La monarchie de droit divin","La séparation des pouvoirs","Le libre-échange"]'::jsonb, 0, 'L’autorité vient de ceux qui obéissent.', 4),
    ('b3d4e8f3-69cc-5e1c-9657-f34a092cd26f'::uuid, '9a4c26dd-f83e-5a15-a234-7f3deaa4e246'::uuid, 'Par quels lieux les idées des Lumières circulent-elles ?', 'mcq', '["Les salons, les cafés, les académies et les loges","Les églises seulement","Les casernes","Les tribunaux"]'::jsonb, 0, 'Les salons étaient souvent tenus par des femmes.', 5),
    ('c2ad4349-af20-5d99-bc45-e7a90f9361d3'::uuid, '9a4c26dd-f83e-5a15-a234-7f3deaa4e246'::uuid, 'Qu’est-ce que le despotisme éclairé ?', 'mcq', '["Un souverain qui réforme au nom des Lumières mais garde tout le pouvoir","Un régime sans roi","Une république","Un gouvernement des philosophes"]'::jsonb, 0, 'Frédéric II, Catherine II, Joseph II.', 6),
    ('7646c35c-c055-5960-8d80-2ca532f30560'::uuid, '9a4c26dd-f83e-5a15-a234-7f3deaa4e246'::uuid, 'Pourquoi certains livres étaient-ils imprimés à l’étranger ?', 'mcq', '["Pour échapper à la censure","Parce que le papier y coûtait moins cher","Pour être traduits","Par tradition"]'::jsonb, 0, 'Ils étaient ensuite vendus sous le manteau.', 7),
    ('dbbbe176-95fa-5097-8a0d-65871594a10b'::uuid, '9a4c26dd-f83e-5a15-a234-7f3deaa4e246'::uuid, 'Les philosophes des Lumières soutenaient la monarchie absolue.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils la critiquaient, ainsi que les privilèges et l’intolérance.', 8),
    ('040e3e3c-1dd8-5500-984c-27de7c4a6342'::uuid, '6449ee0c-3efe-5597-9e13-e4a31277b32e'::uuid, 'Comment s’appellent les trois ordres de l’Ancien Régime ?', 'mcq', '["Clergé, noblesse et tiers état","Roi, nobles et paysans","Nobles, bourgeois et ouvriers","Clergé, armée et peuple"]'::jsonb, 0, 'Le tiers état représente 98 % de la population.', 1),
    ('27977b1e-c317-55d0-8912-aa547abf26c4'::uuid, '6449ee0c-3efe-5597-9e13-e4a31277b32e'::uuid, 'Quelle date marque la prise de la Bastille ?', 'mcq', '["14 juillet 1789","4 août 1789","5 mai 1789","26 août 1789"]'::jsonb, 0, 'La Bastille était le symbole de l’arbitraire royal.', 2),
    ('fa0a54f2-2fef-5c34-bf49-54a17f82b21d'::uuid, '6449ee0c-3efe-5597-9e13-e4a31277b32e'::uuid, 'Qu’est-ce que le serment du Jeu de paume ?', 'mcq', '["L’engagement de ne pas se séparer avant d’avoir donné une constitution","Le couronnement du roi","Un traité de paix","La fondation de la République"]'::jsonb, 0, 'Le 20 juin 1789.', 3),
    ('b2492e4d-4919-578d-997b-746746bf4b66'::uuid, '6449ee0c-3efe-5597-9e13-e4a31277b32e'::uuid, 'Que se passe-t-il dans la nuit du 4 août 1789 ?', 'mcq', '["L’abolition des privilèges","L’exécution du roi","La prise de la Bastille","La déclaration de guerre"]'::jsonb, 0, 'Elle met fin à la société d’ordres.', 4),
    ('523f9509-7463-56b9-b1e3-83ee09a679dd'::uuid, '6449ee0c-3efe-5597-9e13-e4a31277b32e'::uuid, 'Que proclame la Déclaration des droits de l’homme et du citoyen ?', 'mcq', '["Les hommes naissent et demeurent libres et égaux en droits","Le roi est de droit divin","La propriété est abolie","Le suffrage est universel"]'::jsonb, 0, 'Adoptée le 26 août 1789.', 5),
    ('3def88c2-8872-5833-89f5-65ea5ea97ec7'::uuid, '6449ee0c-3efe-5597-9e13-e4a31277b32e'::uuid, 'Qui dénonce dès 1791 l’exclusion des femmes ?', 'mcq', '["Olympe de Gouges","Madame Roland","Charlotte Corday","Marie-Antoinette"]'::jsonb, 0, 'Dans sa Déclaration des droits de la femme et de la citoyenne.', 6),
    ('633d551f-71f3-5bbc-8886-163cf345b5b1'::uuid, '6449ee0c-3efe-5597-9e13-e4a31277b32e'::uuid, 'Qu’est-ce que le suffrage censitaire ?', 'mcq', '["Seuls les hommes payant un certain impôt votent","Tous les hommes votent","Tous les citoyens votent","Le vote est tiré au sort"]'::jsonb, 0, 'Il est instauré par la Constitution de 1791.', 7),
    ('bbabee0f-0cc5-5c70-870b-dcad99693705'::uuid, '6449ee0c-3efe-5597-9e13-e4a31277b32e'::uuid, 'La Déclaration de 1789 s’appliquait aux esclaves des colonies.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ni aux esclaves ni aux femmes — ce que ses critiques ont aussitôt relevé.', 8),
    ('79835186-d6b3-567a-a818-cccc7cfcc6c6'::uuid, '789300b0-318c-509b-839d-0ee4e4e97b7e'::uuid, 'Quel événement de juin 1791 fait perdre au roi la confiance du pays ?', 'mcq', '["La fuite à Varennes","La prise de la Bastille","Le serment du Jeu de paume","La nuit du 4 août"]'::jsonb, 0, 'Il est arrêté et ramené à Paris.', 1),
    ('6766e7de-ba0c-5d9e-beeb-2ae5c4593c9d'::uuid, '789300b0-318c-509b-839d-0ee4e4e97b7e'::uuid, 'Quand la Première République est-elle proclamée ?', 'mcq', '["Le 22 septembre 1792","Le 14 juillet 1789","Le 21 janvier 1793","Le 9 thermidor an II"]'::jsonb, 0, 'Après la prise des Tuileries du 10 août.', 2),
    ('3951cd9b-32fa-593c-95fe-be383a1a2863'::uuid, '789300b0-318c-509b-839d-0ee4e4e97b7e'::uuid, 'Quand Louis XVI est-il exécuté ?', 'mcq', '["Le 21 janvier 1793","Le 10 août 1792","Le 22 septembre 1792","En 1794"]'::jsonb, 0, 'Après un procès devant la Convention.', 3),
    ('754def2f-f45a-5ac4-9452-0d87f099cf56'::uuid, '789300b0-318c-509b-839d-0ee4e4e97b7e'::uuid, 'Quel organe gouverne pendant la Terreur ?', 'mcq', '["Le Comité de salut public","Le Directoire","Les États généraux","Le Sénat"]'::jsonb, 0, 'Dominé par Robespierre.', 4),
    ('4fa6d5f9-c140-58cc-9789-cbaa8a6582e3'::uuid, '789300b0-318c-509b-839d-0ee4e4e97b7e'::uuid, 'Que permet la loi des suspects ?', 'mcq', '["Arrêter sur simple soupçon","Juger avec un avocat","Libérer les prisonniers","Voter la loi"]'::jsonb, 0, 'Elle est au cœur du régime de la Terreur.', 5),
    ('17880507-c00f-5f47-8275-f055f57d2900'::uuid, '789300b0-318c-509b-839d-0ee4e4e97b7e'::uuid, 'Quelle avancée majeure la Convention vote-t-elle en février 1794 ?', 'mcq', '["L’abolition de l’esclavage","Le suffrage féminin","La liberté de la presse","La séparation de l’Église et de l’État"]'::jsonb, 0, 'Bonaparte la rétablira en 1802.', 6),
    ('8d621022-5d20-5183-82a9-496458f492ae'::uuid, '789300b0-318c-509b-839d-0ee4e4e97b7e'::uuid, 'Que se passe-t-il le 9 thermidor an II ?', 'mcq', '["Robespierre est renversé et exécuté","La République est proclamée","Le roi est guillotiné","Bonaparte prend le pouvoir"]'::jsonb, 0, 'Le Directoire lui succède.', 7),
    ('d81a86c0-9755-5ee3-a165-ccce03dee61f'::uuid, '789300b0-318c-509b-839d-0ee4e4e97b7e'::uuid, 'La Constitution de 1793, qui prévoyait le suffrage universel masculin, a été appliquée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle n’a jamais été mise en œuvre.', 8),
    ('c0bbf471-1107-5539-a606-8749a44b67e5'::uuid, '6be4bf09-c0ca-5860-b2cb-f888dda14fb9'::uuid, 'Comment Bonaparte prend-il le pouvoir ?', 'mcq', '["Par le coup d’État du 18 brumaire, en 1799","Par une élection","Par héritage","Par un vote de la Convention"]'::jsonb, 0, 'Il renverse le Directoire.', 1),
    ('6a469eaf-99b2-51f2-876f-947d5d40c789'::uuid, '6be4bf09-c0ca-5860-b2cb-f888dda14fb9'::uuid, 'Quand Napoléon se fait-il sacrer empereur ?', 'mcq', '["Le 2 décembre 1804","En 1799","En 1802","En 1815"]'::jsonb, 0, 'Après avoir été Premier consul puis consul à vie.', 2),
    ('06097e51-e1b1-5660-93d0-e648541fbae5'::uuid, '6be4bf09-c0ca-5860-b2cb-f888dda14fb9'::uuid, 'Quel texte juridique majeur date de 1804 ?', 'mcq', '["Le Code civil","La Déclaration des droits de l’homme","Le Concordat","La Constitution de 1791"]'::jsonb, 0, 'Il inspire encore le droit de nombreux pays.', 3),
    ('f2e4c543-1439-5670-9427-9244fefb5107'::uuid, '6be4bf09-c0ca-5860-b2cb-f888dda14fb9'::uuid, 'Que fait Napoléon de l’esclavage ?', 'mcq', '["Il le rétablit en 1802","Il l’abolit","Il ne s’en occupe pas","Il l’étend à la métropole"]'::jsonb, 0, 'Annulant l’abolition votée en 1794.', 4),
    ('80775f82-719a-5762-b2e7-4eced82608fb'::uuid, '6be4bf09-c0ca-5860-b2cb-f888dda14fb9'::uuid, 'Quelle liberté Napoléon supprime-t-il ?', 'mcq', '["La liberté de la presse","La liberté de culte","La liberté de circulation","Le droit de propriété"]'::jsonb, 0, 'Les journaux sont censurés et les opposants surveillés.', 5),
    ('9511ba1e-4a14-570a-b41a-b7b91ab89476'::uuid, '6be4bf09-c0ca-5860-b2cb-f888dda14fb9'::uuid, 'Quel accord rétablit la paix religieuse en 1801 ?', 'mcq', '["Le Concordat","Le Code civil","L’édit de tolérance","Le Consulat"]'::jsonb, 0, 'Signé avec le pape.', 6),
    ('6f8462f7-5705-5542-8338-3817cc2ea176'::uuid, '6be4bf09-c0ca-5860-b2cb-f888dda14fb9'::uuid, 'Où Napoléon est-il définitivement vaincu, et quand ?', 'mcq', '["À Waterloo, en 1815","À Leipzig, en 1813","En Russie, en 1812","À Austerlitz, en 1805"]'::jsonb, 0, 'Il est exilé à Sainte-Hélène.', 7),
    ('0dc5a2a8-5b08-591e-80d5-41e9ad1d0a26'::uuid, '6be4bf09-c0ca-5860-b2cb-f888dda14fb9'::uuid, 'Le Code civil accordait aux femmes les mêmes droits qu’aux hommes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il plaçait la femme mariée sous l’autorité de son mari.', 8),
    ('841ce378-1387-5f6a-8b4e-435692df6ed6'::uuid, '2aab6875-5eef-575d-85ba-96ab2521b741'::uuid, 'Dans quel pays commence la révolution industrielle ?', 'mcq', '["En Angleterre, vers 1780","En France","En Allemagne","Aux États-Unis"]'::jsonb, 0, 'Elle gagne ensuite le continent.', 1),
    ('08c4cde0-e6ed-5530-809e-d35ad6ebe5eb'::uuid, '2aab6875-5eef-575d-85ba-96ab2521b741'::uuid, 'Quelle invention est au cœur de la première industrialisation ?', 'mcq', '["La machine à vapeur","Le moteur électrique","Le moteur à explosion","La dynamo"]'::jsonb, 0, 'Perfectionnée par James Watt.', 2),
    ('dc99dccb-95da-57f9-96c4-98ac9fab648b'::uuid, '2aab6875-5eef-575d-85ba-96ab2521b741'::uuid, 'Quelles énergies caractérisent la seconde industrialisation ?', 'mcq', '["L’électricité et le pétrole","Le charbon et la vapeur","Le bois et l’eau","Le gaz de ville seul"]'::jsonb, 0, 'À partir de 1870.', 3),
    ('8fe9ddfb-f6eb-58f4-9bd3-9bc6f0b3161d'::uuid, '2aab6875-5eef-575d-85ba-96ab2521b741'::uuid, 'Qu’est-ce que l’exode rural ?', 'mcq', '["Le départ des campagnes vers les villes","L’arrivée de citadins à la campagne","L’émigration vers les colonies","Le retour des ouvriers aux champs"]'::jsonb, 0, 'Il accompagne l’industrialisation.', 4),
    ('e249e07f-3a45-5dfc-8db8-f7e45dcad503'::uuid, '2aab6875-5eef-575d-85ba-96ab2521b741'::uuid, 'Quelle classe devient dominante au XIXe siècle ?', 'mcq', '["La bourgeoisie d’affaires","L’aristocratie foncière","La paysannerie","Le clergé"]'::jsonb, 0, 'Industriels et banquiers.', 5),
    ('d1a8676c-6329-5e9f-96be-ebf2d3423b53'::uuid, '2aab6875-5eef-575d-85ba-96ab2521b741'::uuid, 'Quelle innovation impose une heure unique par pays ?', 'mcq', '["Le chemin de fer","Le télégraphe","L’usine","La banque"]'::jsonb, 0, 'Les horaires de train l’exigeaient.', 6),
    ('45e4bc62-b33d-55aa-bd64-a69181905ead'::uuid, '2aab6875-5eef-575d-85ba-96ab2521b741'::uuid, 'Quel texte majeur du socialisme paraît en 1848 ?', 'mcq', '["Le Manifeste du parti communiste","Le Capital","De l’esprit des lois","Du contrat social"]'::jsonb, 0, 'Par Marx et Engels.', 7),
    ('1831663b-5688-5d91-ac33-56c584b781d8'::uuid, '2aab6875-5eef-575d-85ba-96ab2521b741'::uuid, 'La révolution industrielle a immédiatement amélioré les conditions de vie ouvrières.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Journées de 12 à 15 h, travail des enfants, logements insalubres.', 8),
    ('42ae584f-bc24-5d98-ba62-450d44c9921c'::uuid, '5c6ef884-8ded-5094-ba66-fd40785814a0'::uuid, 'Que possède l’ouvrier du XIXe siècle ?', 'mcq', '["Seulement sa force de travail","Son usine","Sa terre","Ses outils"]'::jsonb, 0, 'Il la vend contre un salaire.', 1),
    ('bac28233-1f41-57ca-ba48-911a2ae54db6'::uuid, '5c6ef884-8ded-5094-ba66-fd40785814a0'::uuid, 'Qui compose la bourgeoisie industrielle ?', 'mcq', '["Industriels, banquiers, commerçants, professions libérales","Paysans et artisans","Nobles de cour","Ouvriers qualifiés"]'::jsonb, 0, 'Elle possède les entreprises.', 2),
    ('caf1fd08-cc88-5e1b-924d-a59991f5ee95'::uuid, '5c6ef884-8ded-5094-ba66-fd40785814a0'::uuid, 'Pourquoi employait-on femmes et enfants dans les usines ?', 'mcq', '["Ils coûtaient moins cher","Ils étaient plus qualifiés","La loi l’imposait","Ils travaillaient moins longtemps"]'::jsonb, 0, 'La France limite le travail des enfants dès 1841.', 3),
    ('2e7bd81b-4ea6-5e72-b770-52681762ce84'::uuid, '5c6ef884-8ded-5094-ba66-fd40785814a0'::uuid, 'Quelle épidémie frappe les quartiers ouvriers surpeuplés ?', 'mcq', '["Le choléra","La peste noire","La variole seule","La grippe espagnole"]'::jsonb, 0, 'Faute d’eau courante et d’égouts.', 4),
    ('8a4c85d5-091d-555b-b33f-7ab5fbbc91ad'::uuid, '5c6ef884-8ded-5094-ba66-fd40785814a0'::uuid, 'En quelle année le droit de grève est-il reconnu en France ?', 'mcq', '["1864","1884","1841","1906"]'::jsonb, 0, 'La liberté syndicale suit en 1884.', 5),
    ('b871d5d5-f9de-5298-bddc-a6efe93161bc'::uuid, '5c6ef884-8ded-5094-ba66-fd40785814a0'::uuid, 'Que défend le libéralisme économique ?', 'mcq', '["L’État doit laisser faire le marché","L’État doit tout posséder","Les salaires doivent être fixés par la loi","Le commerce doit être interdit"]'::jsonb, 0, 'Il s’oppose au socialisme sur ce point.', 6),
    ('fa99d72c-0289-5410-8ab0-e989b8a1fe4b'::uuid, '5c6ef884-8ded-5094-ba66-fd40785814a0'::uuid, 'Quel texte marque l’entrée de l’Église dans la question ouvrière ?', 'mcq', '["Rerum novarum, en 1891","Le Concordat","Le Manifeste communiste","Le Code civil"]'::jsonb, 0, 'C’est l’acte de naissance du catholicisme social.', 7),
    ('383ff8ba-be40-530a-b4ac-cf9d42597a57'::uuid, '5c6ef884-8ded-5094-ba66-fd40785814a0'::uuid, 'Les protections sociales du XIXe siècle ont été accordées spontanément par les patrons.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles ont été arrachées par la mobilisation ouvrière.', 8),
    ('1a02bc5f-8435-5916-aa5a-222fa9417333'::uuid, '63207345-8a93-5dd2-8fce-d090f0fb8b10'::uuid, 'Quelle part des terres émergées l’Europe contrôle-t-elle en 1914 ?', 'mcq', '["Environ 85 %","Environ 40 %","Environ 60 %","Environ 20 %"]'::jsonb, 0, 'Après la conquête de l’Afrique et de l’Asie.', 1),
    ('2282c184-e402-50ba-aa73-ce778ee37cc8'::uuid, '63207345-8a93-5dd2-8fce-d090f0fb8b10'::uuid, 'Que décide la conférence de Berlin de 1884-1885 ?', 'mcq', '["Le partage de l’Afrique entre puissances européennes","L’abolition de l’esclavage","La fin des colonies","La création de la SDN"]'::jsonb, 0, 'Aucun Africain n’y était présent.', 2),
    ('940b1393-d831-58e4-a7b3-ff5d3955f10a'::uuid, '63207345-8a93-5dd2-8fce-d090f0fb8b10'::uuid, 'Quel statut est imposé aux colonisés ?', 'mcq', '["Le statut d’indigène, sans droits politiques","La citoyenneté pleine","Le statut de protégé égal","Aucun statut particulier"]'::jsonb, 0, 'Avec le code de l’indigénat et le travail forcé.', 3),
    ('7d9fbf6a-4924-5b52-af0c-8a3cfc5a9870'::uuid, '63207345-8a93-5dd2-8fce-d090f0fb8b10'::uuid, 'Quel motif idéologique justifiait la colonisation ?', 'mcq', '["La prétendue mission civilisatrice","La liberté des peuples","L’égalité des nations","La paix universelle"]'::jsonb, 0, 'Adossée à des théories racistes.', 4),
    ('3b6a9596-6957-5562-9adb-cfdbcdf87960'::uuid, '63207345-8a93-5dd2-8fce-d090f0fb8b10'::uuid, 'Qui résiste à la conquête française en Algérie ?', 'mcq', '["Abd el-Kader","Samory Touré","Les Cipayes","Les Herero"]'::jsonb, 0, 'Samory Touré résiste en Afrique de l’Ouest.', 5),
    ('1f634697-7a85-5d23-8d6e-fa7a67ab8505'::uuid, '63207345-8a93-5dd2-8fce-d090f0fb8b10'::uuid, 'Quelle révolte éclate en Inde en 1857 ?', 'mcq', '["La révolte des Cipayes","La guerre des Boers","La révolte des Herero","La guerre de l’Opium"]'::jsonb, 0, 'Elle est durement réprimée.', 6),
    ('88047e8e-3742-5f4f-8509-4f6fdafbae8b'::uuid, '63207345-8a93-5dd2-8fce-d090f0fb8b10'::uuid, 'Pourquoi les équipements construits dans les colonies profitent-ils peu aux colonisés ?', 'mcq', '["Ils sont conçus d’abord pour l’exportation","Ils sont trop modernes","Ils sont détruits aussitôt","Ils sont réservés à l’armée"]'::jsonb, 0, 'Les cultures vivrières reculent devant celles d’exportation.', 7),
    ('a05c37df-f915-57ca-9762-3d17cbfe3927'::uuid, '63207345-8a93-5dd2-8fce-d090f0fb8b10'::uuid, 'Les peuples colonisés ne se sont pas opposés à la conquête.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les résistances existent partout et dès le départ.', 8),
    ('a6cce1e9-0e0c-5075-a73a-8111b4088955'::uuid, '6204862a-e0df-5a76-879d-d936a9b9f9b7'::uuid, 'Qu’est-ce que le suffrage censitaire ?', 'mcq', '["Le droit de vote réservé à ceux qui paient un impôt élevé","Le vote de tous les hommes","Le vote par tirage au sort","Le vote des seuls nobles"]'::jsonb, 0, 'Voter y est un privilège de fortune.', 1),
    ('7bbe00fc-4d02-588a-a02f-2a48f0cb67bf'::uuid, '6204862a-e0df-5a76-879d-d936a9b9f9b7'::uuid, 'Quand le suffrage universel masculin est-il proclamé en France ?', 'mcq', '["En 1848","En 1830","En 1870","En 1913"]'::jsonb, 0, 'On passe de 240 000 à 9 millions d’électeurs.', 2),
    ('66118ce0-fe20-5f64-8d44-7eab57c9db36'::uuid, '6204862a-e0df-5a76-879d-d936a9b9f9b7'::uuid, 'Quand les femmes obtiennent-elles le droit de vote en France ?', 'mcq', '["En 1944","En 1848","En 1913","En 1900"]'::jsonb, 0, 'Près d’un siècle après le « suffrage universel » masculin.', 3),
    ('160f7268-ec31-5628-ae2a-1f8aa9ff6923'::uuid, '6204862a-e0df-5a76-879d-d936a9b9f9b7'::uuid, 'Que sont les Trois Glorieuses ?', 'mcq', '["La révolution de 1830","La révolution de 1848","Le coup d’État de 1851","La Commune de 1871"]'::jsonb, 0, 'Elles amènent la Monarchie de Juillet.', 4),
    ('0533bff4-7f6a-5f91-b2ed-479be3ae30da'::uuid, '6204862a-e0df-5a76-879d-d936a9b9f9b7'::uuid, 'Comment Napoléon III encadre-t-il le suffrage universel ?', 'mcq', '["Par la candidature officielle et la censure","En le supprimant","En le réservant aux nobles","En instaurant le tirage au sort"]'::jsonb, 0, 'Le vote existe, le choix est orienté.', 5),
